def solve(data):
    m = data['m']
    if not m:
        return []

    n = len(m)
    m0 = n - 1
    n0 = n - 1

    res = []
    while True:
        for i in range(n0 + 1):
            res.append(m[0][i])
        del m[0]
        if not m:
            break

        for i in range(m0):
            res.append(m[i][-1])
        m0 -= 1
        if not m:
            break

        for i in range(n0, -1, -1):
            res.append(m[-1][i])
        del m[-1]
        if not m:
            break

        for i in range(n0, 0, -1):
            res.append(m[i][0])
        n0 -= 1
        if not m:
            break

    return res
